def set(self, key, value, clock=None):
    if clock is None:
        clock = self._clock
    if value is None:
        self._data[key] = (value, self._clock())
    else:
        self._data[key] = (value, self._clock())

def get(self, key, default=None):
    if key in self._data:
        value, timestamp = self._data[key]
        elapsed = self._clock() - timestamp
        if elapsed >= self.ttl:
            del self._data[key]
            return default
        return value
    return default

